-- Database Alfa Servizi 2026 (gennaio-ottobre) per SQLite
-- Tabelle: agenti, listino, clienti, vendite. Si importa in DB Browser con File > Importa > Database da file SQL.

BEGIN TRANSACTION;

CREATE TABLE agenti (agente TEXT PRIMARY KEY, regione TEXT, obiettivo INTEGER, tariffa REAL);


CREATE TABLE listino (prodotto TEXT PRIMARY KEY, prezzo REAL, costo REAL, categoria TEXT);


CREATE TABLE clienti (cliente TEXT PRIMARY KEY, settore TEXT, citta TEXT, regione TEXT, email TEXT);


CREATE TABLE vendite (ordine TEXT PRIMARY KEY, data TEXT, cliente TEXT, agente TEXT, regione TEXT, canale TEXT, prodotto TEXT, categoria TEXT, quantita INTEGER, prezzo REAL, costo REAL, sconto REAL, importo REAL, stato TEXT);


COMMIT;
